INSERT INTO circles (id, university_id, name, description, status, scope, campus_id,
                     public_listed, public_intro, public_schedule, public_contact) VALUES
  ('b3000000-0000-4000-8000-000000000001', 'b1000000-0000-4000-8000-000000000001', '模擬国連', '旭洋女子大学の学術サークルです。', 'approved', 'university', NULL, true, '興味のあるテーマを持ち寄って、輪読と制作を並行して進めています。成果は学内発表会で共有し、学外のコンテストにも挑戦しています。他学部からの参加も歓迎です。', '毎週水・金 17:30 / 体育館', 'circle1@example.com'),
  ('b3000000-0000-4000-8000-000000000002', 'b1000000-0000-4000-8000-000000000001', '防災ボランティア', '旭洋女子大学の社会サークルです。', 'approved', 'university', NULL, true, '学内だけで完結しない活動を心がけています。地域の団体と連携した企画を月1回のペースで実施しており、参加の頻度は各自の予定に合わせて調整できます。', '隔週土曜 13:00 / 学外練習場', 'circle2@example.com'),
  ('b3000000-0000-4000-8000-000000000003', 'b1000000-0000-4000-8000-000000000001', '文芸部', '旭洋女子大学の文化サークルです。', 'approved', 'university', 'b2000000-0000-4000-8000-000000000001', true, '作品づくりと発表を軸に活動しています。週1回の集まりでは、お互いの作品を持ち寄って感想を交わします。展示や上演は学園祭のほか、学外の企画にも参加しています。', '毎週月曜 18:30 / 音楽練習室', 'circle3@example.com'),
  ('b3000000-0000-4000-8000-000000000004', 'b1000000-0000-4000-8000-000000000001', 'アカペラサークル', '旭洋女子大学の音楽サークルです。', 'approved', 'university', 'b2000000-0000-4000-8000-000000000001', true, '週に2回、部室とスタジオで練習しています。初心者からでも始められるよう、パート別の練習日を設けています。学園祭と定期演奏会が年2回の大きな舞台です。', '隔週土曜 13:00 / 学外練習場', 'circle4@example.com'),
  ('b3000000-0000-4000-8000-000000000005', 'b1000000-0000-4000-8000-000000000001', '経済学研究会', '旭洋女子大学の学術サークルです。', 'approved', 'university', 'b2000000-0000-4000-8000-000000000002', true, '興味のあるテーマを持ち寄って、輪読と制作を並行して進めています。成果は学内発表会で共有し、学外のコンテストにも挑戦しています。他学部からの参加も歓迎です。', '毎週水・金 17:30 / 体育館', 'circle5@example.com'),
  ('b3000000-0000-4000-8000-000000000006', 'b1000000-0000-4000-8000-000000000001', 'バドミントン部', '旭洋女子大学のスポーツサークルです。', 'approved', 'university', 'b2000000-0000-4000-8000-000000000001', true, '経験者も初心者も一緒に活動しています。ケガを防ぐことを第一に、練習の前後は必ず全員でストレッチを行います。年に数回、近隣の大学と合同で練習試合を組んでいます。', '毎週月曜 18:30 / 音楽練習室', 'circle6@example.com'),
  ('b3000000-0000-4000-8000-000000000007', 'b1000000-0000-4000-8000-000000000001', '国際交流サークル', '旭洋女子大学の社会サークルです。', 'approved', 'university', 'b2000000-0000-4000-8000-000000000001', true, '学内だけで完結しない活動を心がけています。地域の団体と連携した企画を月1回のペースで実施しており、参加の頻度は各自の予定に合わせて調整できます。', '毎週火曜 18:00 / 第1部室', 'circle7@example.com'),
  ('b3000000-0000-4000-8000-000000000008', 'b1000000-0000-4000-8000-000000000002', '手話サークル', '青葉大学の社会サークルです。', 'approved', 'university', NULL, true, '学内だけで完結しない活動を心がけています。地域の団体と連携した企画を月1回のペースで実施しており、参加の頻度は各自の予定に合わせて調整できます。', '毎週水・金 17:30 / 体育館', 'circle8@example.com'),
