-- 確認用
SELECT
  (SELECT count(*) FROM universities) AS universities,
  (SELECT count(*) FROM campuses)     AS campuses,
  (SELECT count(DISTINCT prefecture) FROM campuses) AS prefectures,
  (SELECT count(*) FROM circles WHERE status='approved') AS circles,
  (SELECT count(*) FROM events WHERE event_date > now()) AS events,
  (SELECT count(*) FROM events WHERE event_date > now() AND public_listed) AS public_events;
